import re

# Parse the raw cell data into structured rows
lines = order_summary_raw.strip().split('\n')
rows = {}
for line in lines:
    # Match patterns like (row, col): value
    matches = re.findall(r'\((\d+),\s*(\d+)\):\s*([^\t]*)', line)
    for row_num, col_num, value in matches:
        r, c = int(row_num), int(col_num)
        if r not in rows:
            rows[r] = {}
        rows[r][c] = value.strip()

# Build CSV content
csv_lines = []
max_col = 6  # 6 columns: Order ID, Customer, Date, Status, Items, Total Paid
for r in sorted(rows.keys()):
    row_vals = []
    for c in range(1, max_col + 1):
        val = rows[r].get(c, '')
        # Quote values containing commas
        if ',' in val:
            val = f'"{val}"'
        row_vals.append(val)
    csv_lines.append(','.join(row_vals))

csv_content = '\n'.join(csv_lines)
print(f"Parsed {len(rows)} rows, {max_col} columns")
print("First 3 lines preview:")
for line in csv_lines[:3]:
    print(line)
